#include <cmath>

class C3DVector { public: float X, Y, Z; };
struct CTCGraphicAppearance {
    C3DVector Focal;
    C3DVector GetFocalPos(float scale) const { C3DVector r = Focal; r.Z *= scale; return r; }
};
